def museum_of(text):
    t = text or ''
    return next((x for x in sorted(MUS, key=lambda x: -len(x['name'])) if x['name'] in t or x['name'].replace('博物馆', '博') in t or (len(x['name']) > 4 and t and t in x['name'] and len(t) >= 4) or any(a and a in t for a in x.get('alias', []))), None)


