for _a, _b in (('故宫博物院', '故宫'), ('天坛公园', '天坛'), ('颐和园景区', '颐和园'), ('兵马俑', '秦始皇帝陵博物院'), ('布达拉宫广场', '大昭寺')):
    if _b in DEEP and _a not in DEEP and _a != '布达拉宫广场': DEEP[_a] = DEEP[_b]

STORY_NOW = ['']   # 当前这一天的“懂一点”原文


CLOSING_RE = re.compile(r'博物馆|博物院|美术馆|纪念馆|故居|旧址|陈列馆|科技馆|展览馆|寺|庙|祠|观$|道观|文庙|孔庙|府$|衙|石窟|陵|馆$')
NOT_CLOSING_RE = re.compile(r'夜|市场|老街|步行街|公园|广场|码头|观景|日落|夜游|演出|灯光|夜景')


def row_html(w, city, app):
    t = w['type']
    if t == 'dep':
        sub = E(w.get('how')) if w.get('how') else ''
        return f'<li class="r dep"><time>{E(w["t"])}</time><span class="dot"></span><div class="rb"><p class="m">出发 → {E(w.get("to"))}</p>{f"<p class=s>{sub}</p>" if sub else ""}</div></li>'
    if t == 'eat':
        place = w.get('place') if w.get('place') not in ('随意', '住的地方附近', '附近', '车站或机场里吃', '沿途', '路上') else ''
        main = f'{E(w.get("slot"))} · {E(w.get("dish"))}'
        rec = [x for d_ in re.split(r'[、，]', w.get('dish') or '') for x in FAMOUS.get(city or '', {}).get(d_.strip(), [])]
        tip = ('老店：' + '、'.join(rec)) if rec else ''
        sub = ' · '.join(x for x in [E(place), E(w.get('d')), E(w.get('kb')), E(tip)] if x)
        kw = w.get('poi') or place
    elif t == 'stay':
        main = '住 · ' + E(w.get('name')); sub = E(w.get('d')); kw = w.get('poi')
        if not w.get('dp'):
            ic = f'<a class="ic" href="{E(mapurl(kw, city, app))}" rel="nofollow noopener" target="_blank" aria-label="地图上看 {E(kw)}">{ICON_PIN}</a>' if kw else ''
            return f'<li class="r stay"><time>{E(w["t"])}</time><span class="dot"></span><div class="rb"><p class="m">{main}{ic}</p>{f"<p class=s>{sub}</p>" if sub else ""}</div></li>'
    else:
        main = E(w.get('name')); sub = ' · '.join(x for x in [E(w.get('d')), E(w.get('kb'))] if x); kw = w.get('poi')
        mu = museum_of(w.get('name')) or museum_of(w.get('poi'))
        bk_ = book_of(w.get('name')); sg_ = sight_of(w.get('name')); tx_ = tix_of(w.get('name'))
        if tx_:   # 时长、门票、一句话并成一行：门票写短（“约 100 元”），开放时间不写，只留“周一闭馆”这种
            _tt = re.sub(r'（要(实名)?预约）', '', tx_.get('t') or '') if bk_ else (tx_.get('t') or '')   # 上面已经写了“要预约”
            _tt = re.sub(r'(\d[\d,]*)\s*元左右', r'约 \1 元', _tt); _tt = re.sub(r'^门票\s*', '', _tt)
            _tx = ' · '.join(x for x in [(_tt if '免费' in _tt[:6] else '门票' + ('' if _tt.startswith(('约', '旺季')) else ' ') + _tt) if _tt else '', tx_.get('c', '')] if x)
            if _tx: sub = (sub + ' · ' if sub else '') + '<span class="tix">' + E(_tx) + '</span>'
            if '周一闭馆' in _tx and sg_: sg_ = re.sub(r'[，、]?周一闭馆', '', sg_)     # 门票那一行已经写了，一句话里不再重复
        if sg_ and not (mu and mu['treasures']) and re.split(r'\s*·\s*', w.get('name') or '')[0] not in STORY_NOW[0]: sub = (sub + ' · ' if sub else '') + '<span class="sn2">' + E(sg_) + '</span>'   # 懂一点里讲过的不再重复
        if mu and mu['treasures']:
            main += '<span class="gb">国宝</span>'
            note_ = re.sub(r'，?(要提前预约|要预约)', '', mu.get('note') or '').strip('，')
            sub = (sub + '</p><p class="s tre">' if sub else '') + '<b>镇馆之宝</b>' + E('、'.join(mu['treasures'])) + (('，' + E(note_)) if note_ else '')
        if bk_:
            u_ = BOOK_URL.get(bk_[0]); h_ = BOOK_HOW.get(bk_[0], '')
            tag_ = (f'<a class="bkn bkl" href="{E(u_)}" rel="nofollow noopener" target="_blank">要预约 ›</a>' if u_ else f'<em class="bkn" data-how="{E(h_)}">要预约{("（" + ("小程序" if "小程序" in h_ else "公众号") + "）") if h_ else ""}</em>')
            sub = tag_ + (' · ' if sub else '') + sub
    if t in ('see', 'fun') and CLOSING_RE.search(w.get('name') or '') and not NOT_CLOSING_RE.search(w.get('name') or ''):      # 按时关门的馆、寺、祠、故居排到傍晚：提醒先看官网（多数 17 点前后停止入场）
        _st = int(w['t'][:2]) * 60 + int(w['t'][3:5]); _h = re.search(r'(\d+) 小时', w.get('d') or ''); _m = re.search(r'(\d+) 分', w.get('d') or '')
        if _st >= 16 * 60 + 45 or _st + (int(_h.group(1)) * 60 if _h else 0) + (int(_m.group(1)) if _m else 0) > 17 * 60 + 45:
            sub = (sub + ' · ' if sub else '') + '<span class="tix">傍晚可能已停止入场，出发前看一眼官网</span>'
    _core = re.split(r'\s*[·（(]\s*', (w.get('name') or ''))[0].strip()
    _xk = (f'{city} {_core}' if city and city not in _core else _core) if (t in ('see', 'fun') and _core and re.search(r'[\u4e00-\u9fff]', _core) and '沿途' not in _core) else None   # 小红书按“城市 景点名”搜，用中文名，不用导航用的查询词
    ic = icons(kw, city, app, w.get('dp'), w.get('nav'), w.get('navp'), _xk) if kw else ''
    if t == 'eat' and not kw:   # 没有具体地方的饭：只放点评，按“城市 + 菜名”找
        ic = f'<a class="ic dp" href="{E(dpurl(w.get("dish") or "", city))}" data-app="{E("dianping://searchshoplist?keyword=" + urllib.parse.quote((city or "") + " " + (w.get("dish") or "")))}" rel="nofollow noopener" target="_blank" aria-label="大众点评上找 {E(w.get("dish"))}">{ICON_DP}</a>'
    da = (f' data-at="{E(w["at"])}"' if w.get('at') else '') + (f' data-meal="{"l" if w.get("slot") == "午饭" else "d" if w.get("slot") == "晚饭" else "b"}"' if t == 'eat' else '') + (' data-in="1"' if t in ('see', 'fun') and INDOOR_RE.search(w.get('name') or '') else '') + (f' data-cw="{(FOREIGN_CLOSED[w["name"]] + 1) % 7}"' if t in ('see', 'fun') and app != 'amap' and (w.get('name') or '') in FOREIGN_CLOSED else '')
    return f'<li class="r {t}"{da}><time>{E(w["t"])}</time><span class="dot"></span><div class="rb"><p class="m">{main}{ic}</p>{f"<p class=s>{sub}</p>" if sub else ""}</div></li>'


WEEK = '一二三四五六日'
# 国外去处的每周固定闭馆日（Python weekday：周一=0…周日=6）。只放网上查到多处一致的；名字必须整名相等（“卢浮宫阿布扎比”是另一座，不算）
FOREIGN_CLOSED = {'卢浮宫': 1, '奥赛博物馆': 0, '凡尔赛宫': 0, '乌菲兹美术馆': 0, '梵蒂冈博物馆': 6, '托普卡帕宫': 1, '景福宫': 1, '昌德宫': 0, '无忧宫': 0, '国家人类学博物馆': 0}


def fclosed_days(r):
    """国外线里（天序号, python 周几）：那一天有每周固定闭馆的去处"""
    out = []
    if r.get('navApp') == 'amap': return out
    for i, d in enumerate(r['days']):
        for w in d['rows']:
            if w['type'] in ('see', 'fun') and (w.get('name') or '') in FOREIGN_CLOSED: out.append((i, FOREIGN_CLOSED[w['name']]))
    return out


# 法定假日出行高峰窗口（含前后返程高峰的大致范围；放假和调休每年 11 月才由国务院公布，这里是按节日日期估的，页面提示里写“以公布为准”）。site.js 里有同一张表，改动要两边一起
HOLIDAYS = [('元旦', '2027-01-01', '2027-01-03'), ('春节', '2027-02-04', '2027-02-14'), ('清明', '2027-04-03', '2027-04-05'), ('五一', '2027-05-01', '2027-05-05'), ('端午', '2027-06-09', '2027-06-11'),
            ('中秋', '2027-09-15', '2027-09-17'), ('国庆', '2027-10-01', '2027-10-07'), ('元旦', '2028-01-01', '2028-01-03'), ('春节', '2028-01-24', '2028-02-03'), ('清明', '2028-04-04', '2028-04-06'),
            ('五一', '2028-05-01', '2028-05-05'), ('端午', '2028-05-27', '2028-05-29'), ('国庆', '2028-10-01', '2028-10-07')]


def holiday_hit(start, n):
    """默认行程 [start, start+n-1] 和哪些假日窗口相交"""
    end = start + datetime.timedelta(days=n - 1)
    return [h[0] for h in HOLIDAYS if datetime.date.fromisoformat(h[1]) <= end and start <= datetime.date.fromisoformat(h[2])]


def mon_days(r):
    """行程里哪几天（从 0 数）有周一闭馆的去处"""
    out = []
    for i, d in enumerate(r['days']):
        for w in d['rows']:
            if w['type'] in ('see', 'fun'):
                tx = tix_of(w.get('name')) or {}
                nm_ = w.get('name') or ''
                maybe_ = r.get('navApp') == 'amap' and INDOOR_RE.search(nm_) and not re.search(r'秦始皇帝陵|兵马俑', nm_)     # 国内没标的博物馆也避开周一（页面上给软提示）
                if '周一闭馆' in (tx.get('c') or '') or '周一闭馆' in (w.get('kb') or '') or '周一闭馆' in (sight_of(w.get('name')) or '') or maybe_: out.append(i); break
    return out


def start_date(r):
    st = r.get('start') or [TODAY.year, TODAY.month - 1, TODAY.day]
    d = datetime.date(st[0], st[1] + 1, min(st[2], calendar.monthrange(st[0], st[1] + 1)[1]))
    while d < TODAY: d = d.replace(year=d.year + 1)
    # 正当季（今天落在“最好的日子”里）：默认出发日要落在窗口内，不能顺延到明年（首页封面写着“还剩 7 天”，点进去却是明年）
    t = TRIP_OF_ROUTE.get(r.get('id')) or {}
    b = (t.get('season') or {}).get('best')
    end = None
    if b and not t.get('anytime'):
        md0 = TODAY.strftime('%m-%d'); wrap = b[0] > b[1]
        if (md0 >= b[0] or md0 <= b[1]) if wrap else (b[0] <= md0 <= b[1]):
            end = datetime.date(TODAY.year + (1 if wrap and md0 >= b[0] else 0), int(b[1][:2]), int(b[1][3:]))
            cand = TODAY + datetime.timedelta(days=(5 - TODAY.weekday()) % 7)      # 下一个周六，且至少两天后
            if (cand - TODAY).days < 2: cand += datetime.timedelta(days=7)
            d = cand if cand <= end else max(TODAY + datetime.timedelta(days=1), end)
    # 行程里有“周一闭馆”的去处：默认日期要避开让那一天落在周一（先试后一天、前一天，再远一点；不出窗口、不早于明天）
    mons = mon_days(r); fcl = fclosed_days(r); own_hol = any(x in ' '.join(r.get('prep') or []) for x in ('春节', '国庆', '五一', '中秋', '端午', '清明'))     # 线路本来就为假日做的（蔚县打树花）不避
    if mons or fcl or not own_hol:
        lo = TODAY + datetime.timedelta(days=1); found = False
        for lim in (end, None):      # 先在“最好的日子”窗口里找；窗口太窄（今天离窗口结束只剩一两天）找不到，就放宽到窗口外几天，也不让周一闭馆的那天落在周一
            for off in [0] + [x * y for x in range(1, 13) for y in (1, -1)]:
                c_ = d + datetime.timedelta(days=off)
                if c_ < lo or (lim and c_ > lim): continue
                if all((c_ + datetime.timedelta(days=i)).weekday() != 0 for i in mons) and all((c_ + datetime.timedelta(days=i)).weekday() != wd for i, wd in fcl) and (own_hol or not holiday_hit(c_, len(r['days']))): d = c_; found = True; break
            if found or not end: break
    return d


CT = json.load(open('data/ctrip_city.json')) if os.path.exists('data/ctrip_city.json') else {'city': {}, 'district': {}}
CT_ALIAS = {'万盛': '重庆', '南川': '重庆', '大足': '重庆', '江津': '重庆', '涪陵': '重庆', '武隆': '重庆', '黔江': '重庆', '东川': '昆明', '乃东': '山南', '扎囊': '山南',
            '九华山': '池州', '二道白河': '延边', '五台山': '忻州', '克什克腾': '赤峰', '冷湖': '海西', '大柴旦': '海西', '勐仑': '西双版纳', '南岳': '衡阳', '唐克': '阿坝',
            '大丰': '盐城', '奉化': '宁波', '崇礼': '张家口', '昌平': '北京', '横店': '金华', '武功山': '萍乡', '武当山': '十堰', '永年': '邯郸', '沱沱河': '格尔木', '海拉尔': '呼伦贝尔',
            '淮阳': '周口', '磨西': '康定', '蓟州': '天津', '蓬莱': '烟台', '虎头': '鸡西', '顺德': '佛山', '黄陂': '武汉', '龙虎山': '鹰潭', '东极': '舟山', '乌布': '巴厘岛', '美瑛': '旭川'}


def ctrip_city(c):
    for k in (c, (c or '') + '市', (c or '') + '县', (c or '') + '地区', (c or '').rstrip('市县')):
        if k in CT['city']: return CT['city'][k]
    for k in (c, (c or '') + '县', (c or '') + '市', (c or '') + '镇'):
        if k in CT['district']: return CT['district'][k]
    return None


def hotel_url(keyword, city, app='amap', base=None):
    """订酒店链接：携程手机版要带城市编号才按关键词搜（不带会默认显示上海）；携程查不到这个城市就用地图搜酒店"""
    cid = ctrip_city(city) or ctrip_city(CT_ALIAS.get(city, '')) or (ctrip_city(base) if base else None)
    if cid: return f'https://m.ctrip.com/webapp/hotels/list?city={cid}&keyword={urllib.parse.quote(keyword)}'
    if app == 'google': return 'https://www.google.com/maps/search/?api=1&query=' + urllib.parse.quote(keyword + ' hotel')
    return 'https://uri.amap.com/search?keyword=' + urllib.parse.quote(keyword) + '&city=' + urllib.parse.quote(city or '') + '&src=zouni&callnative=1'


GENERIC_STAY = re.compile(r'(附近|市区|县城|老城|古城|市中心|城里|边上|一带|营地|客栈|民宿)$')


def _km(a, b):
    import math as _m
    r = _m.pi / 180; dl = (b[1] - a[1]) * r; p1, p2 = a[0] * r, b[0] * r
    return 2 * 6371 * _m.asin(_m.sqrt(_m.sin((p2 - p1) / 2) ** 2 + _m.cos(p1) * _m.cos(p2) * _m.sin(dl / 2) ** 2))


def stay_fix(r):
    """每天晚上实际住哪：返回 [(住处名, 回住处的交通说明或 None)]
    只改一种明确的错：当天已经到了下一个地方（离前一天最后一站 60 公里以上、第二天也从这附近出发），住处却还写着前一天那家；
    回住处的车程只在 30–120 公里之间、两头坐标都可信时才写"""
    out = []; n_ = len(r['days'])
    def pts(d):
        c = d.get('navCity') or d.get('city')
        return [coord(w['poi'], c) for w in d['rows'] if w['type'] in ('see', 'fun', 'eat') and w.get('poi') and coord(w['poi'], c)]
    P = [pts(d) for d in r['days']]
    prev_nm = None
    for i, d in enumerate(r['days']):
        nm = d['stay'][0]['name'] if d.get('stay') else d.get('stayName')
        if i == n_ - 1 or not nm or d.get('stay'): out.append((nm, None)); prev_nm = nm; continue
        city = d.get('navCity') or d.get('city'); last = P[i][-1] if P[i] else None
        plast = P[i - 1][-1] if i > 0 and P[i - 1] else None; nf = P[i + 1][0] if P[i + 1] else None
        if prev_nm and nm == prev_nm and last and plast and _km(last, plast) > 60 and (nf is None or _km(last, nf) < 60):
            pcity = r['days'][i - 1].get('navCity') or r['days'][i - 1].get('city')
            if city and city != pcity: nm = city + '附近'
        how = None
        cc = GEO.get((city or '') + '|' + (city or '')); ccp = (cc['lat'], cc['lng']) if cc else None
        core = GENERIC_STAY.sub('', nm or '').strip()
        sp = coord(core, city) or coord(nm, city) or (ccp if core in ('', city) else None)
        if sp and ccp and _km(sp, ccp) > 80: sp = None
        if last and sp and 30 < _km(last, sp) <= 120:
            out0 = next((w['how'] for w in d['rows'] if w['type'] == 'dep' and w.get('how')), '') or ''
            if plast and P[i] and _km(plast, P[i][0]) > 100: out0 = ''       # 转场日：第一段是从上一座城过来的高铁，不是“当天往返”的去程，回住处不能照抄（slgt8 晚上 3 小时 30 分高铁回住处）
            if re.search(r'JR|高铁|动车|火车|地铁|轮渡|坐船|公交|大巴|快艇', out0):
                how = re.split(r'\s*·\s*', out0)[0]            # 去的时候坐什么，回来也坐什么
            else:
                mins = int(_km(last, sp) * 1.3)
                how = (('自驾约 ' if any((w_.get('how') or '').startswith(('自驾', '开车')) for dd_ in r['days'] for w_ in dd_['rows']) else '包车约 ') + (f'{mins // 60} 小时' + (f' {mins % 60} 分' if mins % 60 >= 10 else '') if mins >= 60 else f'{mins} 分钟') + f' · {round(_km(last, sp) * 1.3)} 公里')
        if nm in ('古城', '老城', '市区', '市中心', '县城', '城里', '新城') and city: nm = city + nm
        out.append((nm, how)); prev_nm = d['stay'][0]['name'] if d.get('stay') else d.get('stayName')
    return out


DAY_PT = {}


def day_point(rr, k):
    key = (id(rr), k)
    if key in DAY_PT: return DAY_PT[key]
    d = rr['days'][k]; c = d.get('navCity') or d.get('city')
    ps = [coord(w['poi'], c) for w in d['rows'] if w['type'] in ('see', 'fun') and w.get('poi') and coord(w['poi'], c)]
    cc = GEO.get((c or '') + '|' + (c or ''))
    if cc: ps = [p_ for p_ in ps if _km(p_, (cc['lat'], cc['lng'])) < 150] or [(cc['lat'], cc['lng'])]   # 按名字查到外地同名的点不算
    DAY_PT[key] = (sum(p[0] for p in ps) / len(ps), sum(p[1] for p in ps) / len(ps)) if ps else None
    return DAY_PT[key]


_CAND_POOL = None
_core = lambda x: re.split(r'\s*·\s*', x or '')[0].strip()


def _cand_pool():
    """所有可以“接上”的一天（别的线里不是赶路、不是回程的天），只算一次"""
    global _CAND_POOL
    if _CAND_POOL is None:
        pool = []
        for o, rr in ROUTES.items():
            for k, dd in enumerate(rr['days']):
                ttl = dd.get('title') or ''
                if re.search(r'回|→|出发|去|到达|抵达|还车|提车', ttl): continue
                pt = day_point(rr, k) or ((dd['lat'], dd['lng']) if dd.get('lat') and dd.get('lng') else None)   # 景点没坐标的，用这一天的落脚点
                if not pt: continue
                names = [w.get('name') for w in dd['rows'] if w['type'] in ('see', 'fun')]
                if not names: continue
                pool.append((o, k, ttl, pt, [_core(x) for x in names], rr.get('label')))
        _CAND_POOL = pool
    return _CAND_POOL


def add_cands(rid, r):
    """加一天的候选：离这条线每一天（最后一天除外）100 公里以内的、别的线里的一天；d 记“离第几天多远”，在哪天后面加就按离那天的远近排"""
    n_ = len(r['days'])
    if n_ < 2: return []
    pts = [day_point(r, k) or ((r['days'][k]['lat'], r['days'][k]['lng']) if r['days'][k].get('lat') and r['days'][k].get('lng') else None) for k in range(n_ - 1)]
    mine = {_core(w.get('name')) for d in r['days'] for w in d['rows'] if w['type'] in ('see', 'fun')}
    best = []
    for (o, k, ttl, pt, cores, label) in _cand_pool():
        if o == rid: continue
        if sum(1 for x in cores if x in mine) >= max(1, len(cores) // 2 + (len(cores) % 2)): continue   # 一半以上已经在这条线里
        dd = {}
        for j, bp in enumerate(pts):
            if not bp or abs(bp[0] - pt[0]) > 1.0 or abs(bp[1] - pt[1]) > 1.4: continue
            km = _km(bp, pt)
            if km <= 100: dd[j] = round(km)
        if dd: best.append({'rid': o, 'label': label, 'i': k, 'title': ttl, 'lat': round(pt[0], 4), 'lng': round(pt[1], 4), 'd': dd, 'km': min(dd.values())})
    best.sort(key=lambda x: x['km'])
    seen = set(); res = []
    for x in best:
        if x['title'] in seen: continue
        seen.add(x['title']); res.append(x)
    keep = set()
    for j in range(n_ - 1):
        for x in sorted([x for x in res if j in x['d']], key=lambda x: x['d'][j])[:10]: keep.add(id(x))
    return [x for x in res if id(x) in keep]


HOTELS = json.load(open('data/hotels/ctrip_hotels.json')) if os.path.exists('data/hotels/ctrip_hotels.json') else {}


def hotel_pick(city, area):
    """携程上这个住处的真实酒店（抓下来的）：返回 (三档, 高分列表)"""
    cid = ctrip_city(city) or ctrip_city(CT_ALIAS.get(city, ''))
    if not cid: return None, None
    kw = re.sub(r'(附近|一带|边上|边|里|市区)$', '', area) if area and area != city else city
    h = HOTELS.get(f'{cid}|{kw}') or {}
    return ({k: h[k] for k in ('lux', 'mid', 'eco') if h.get(k)} or None), (h.get('top') or None)


def ctrip_detail(hid): return f'https://m.ctrip.com/html5/hotel/hoteldetail/{hid}.html'


def kfmt(v):
    v = round(v / 100) / 10
    return (f'{v:.1f}'.rstrip('0').rstrip('.')) if v < 100 else f'{v:.0f}'


def price_k(p):
    """¥2,800–3,800 → ¥2.8–3.8K（短，放得下）"""
    ns = []
    for x in re.findall(r'\d[\d,]*(?:\.\d+)?', p or ''):      # “¥8,900.0–18,500.0”：带小数的整串当一个数，不能拆出 0
        try: ns.append(int(round(float(x.replace(',', '')))))
        except ValueError: pass
    if not ns: return p or ''
    return '¥' + (kfmt(ns[0]) + 'K–' + kfmt(ns[1]) + 'K' if len(ns) > 1 else kfmt(ns[0]) + 'K')


TIX = json.load(open('data/catalog/tickets.json')) if os.path.exists('data/catalog/tickets.json') else {}
INDOOR_RE = re.compile(r'博物馆|博物院|美术馆|纪念馆|展览馆|科技馆|陈列馆|艺术馆|天文馆|海洋馆|水族馆')


def tix_of(name):
    n_ = name or ''
    k = next((k for k in sorted(TIX, key=len, reverse=True) if k in n_ and not _den('TIX', k)), None)
    return TIX[k] if k else None


INDOOR = []


def indoor_list():
    """所有行程里出现过、有坐标的室内去处（下雨时换着去）"""
    if INDOOR: return INDOOR
    seen = set()
    for rr in ROUTES.values():
        for d in rr['days']:
            c = d.get('navCity') or d.get('city')
            for w in d['rows']:
                nm = w.get('name') or ''
                if w['type'] in ('see', 'fun') and INDOOR_RE.search(nm) and w.get('poi'):
                    core = re.split(r'\s*·\s*', nm)[0]
                    if core in seen: continue
                    pt = coord(w['poi'], c)
                    if pt: seen.add(core); INDOOR.append({'n': core, 'q': w['poi'], 'c': c, 'lat': round(pt[0], 4), 'lng': round(pt[1], 4)})
    return INDOOR


def indoor_near(r):
    pts = [p_ for k in range(len(r['days'])) for p_ in [day_point(r, k)] if p_]
    mine = {re.split(r'\s*·\s*', w.get('name') or '')[0] for d in r['days'] for w in d['rows']}
    out = []
    for x in indoor_list():
        if x['n'] in mine: continue
        dmin = min((_km((x['lat'], x['lng']), p_) for p_ in pts), default=999)
        if dmin <= 60: out.append(dict(x, km=round(dmin)))
    out.sort(key=lambda x: x['km'])
    return out[:20]


NEAR = []


def near_list():
    if NEAR: return NEAR
    seen = set()
    for rr in ROUTES.values():
        for d in rr['days']:
            c = d.get('navCity') or d.get('city')
            for w in d['rows']:
                nm = w.get('name') or ''
                if w['type'] not in ('see', 'fun') or not w.get('poi') or '沿途' in nm or '提车' in nm or '还车' in nm: continue
                core = re.split(r'\s*·\s*', nm)[0]
                if core in seen: continue
                pt = coord(w['poi'], c)
                if not pt: continue
                m_ = re.search(r'(\d+) 小时', w.get('d') or ''); m2 = re.search(r'(\d+) 分', w.get('d') or '')
                dur = (int(m_.group(1)) * 60 if m_ else 0) + (int(m2.group(1)) if m2 else 0) or 90
                seen.add(core); NEAR.append({'n': core, 'c': c, 'lat': round(pt[0], 4), 'lng': round(pt[1], 4), 'dur': dur})
    return NEAR


def near_for(r):
    pts = [p_ for k in range(len(r['days'])) for p_ in [day_point(r, k)] if p_]
    mine = {re.split(r'\s*·\s*', w.get('name') or '')[0] for d in r['days'] for w in d['rows']}
    out = []
    for x in near_list():
        if x['n'] in mine: continue
        dmin = min((_km((x['lat'], x['lng']), p_) for p_ in pts), default=999)
        if dmin <= 25: out.append(x)
    out.sort(key=lambda x: min(_km((x['lat'], x['lng']), p_) for p_ in pts))
    return out[:30]


def addday_city(r, SF):
    """加一天时“在哪多留一天”：住处名像酒店（酒店、宾馆、民宿、客栈……）就用城市名"""
    nm = (SF[-2][0] if len(SF) > 1 and SF[-2][0] else '') or ''
    city = (r['days'][-2].get('navCity') or r['days'][-2].get('city')) if len(r['days']) > 1 else (r['days'][0].get('navCity') or r['days'][0].get('city'))
    if not nm or re.search(r'酒店|宾馆|饭店|民宿|客栈|旅舍|度假村|山庄|公寓', nm): return city or nm
    return nm


RCENT = {}


def route_center(o):
    if o in RCENT: return RCENT[o]
    rr = ROUTES[o]; ps = [p_ for k in range(len(rr['days'])) for p_ in [day_point(rr, k)] if p_]
    RCENT[o] = (sum(p_[0] for p_ in ps) / len(ps), sum(p_[1] for p_ in ps) / len(ps)) if ps else None
    return RCENT[o]


def nearby_routes(rid, k=3):
    """附近还能去：离这条线中心最近的几条（不含自己、不含跨省全国长线，同一目的地最多一条）"""
    c0 = route_center(rid)
    if not c0: return []
    out = []
    for o in ROUTE_IDS:
        if o == rid or not TRIP_OF_ROUTE.get(o): continue
        if set(TRIP_OF_ROUTE[o].get('tags') or []) & {'跨省', '全国'}: continue
        c1 = route_center(o)
        if not c1: continue
        dk = _km(c0, c1)
        if dk < 5 or dk > 600: continue
        out.append((dk, o))
    out.sort(); res = []; seen = set()
    for dk, o in out:
        lab = re.sub(r'\s*\d+\s*天$', '', ROUTES[o].get('label') or '')
        if lab in seen: continue
        seen.add(lab); res.append((dk, o))
        if len(res) >= k: break
    return res


