    print('长线文案串位（被拒绝）', len(set(COLL)), '条（详见 build/long_collisions.txt）')
    print('网站', OUT, '· 行程页', len(ROUTE_IDS), '· 目的地页', len(CAT['destinations']), '· 文件', n)
